import { useParams } from 'react-router-dom'
import Header from '../../components/Header'
import Footer from '../../components/Footer'
import Banner from '../../components/Banner'
import ProductsList from '../../components/ProductsList'
import hiokisushi from '../../assets/pratos/Hioki Sushi/hiokisushi.png'
import ladocevita from '../../assets/pratos/La Dolce Vita Trattoria/image 1.png'
import diablo from '../../assets/images/diablo.png'
import starWars from '../../assets/images/star_wars.png'

// Tipando explicitamente as chaves como strings específicas
interface Prato {
  title: string
  description: string
  image: string
  infos: string[]
}

// Agora pratoData é um objeto com chaves fixas ('1', '2', '3', etc.)
const pratoData: Record<'1' | '2' | '3' | '4', Prato> = {
  '1': {
    title: 'Hioki Sushi',
    description:
      'Peça já o melhor da culinária japonesa no conforto da sua casa...',
    image: hiokisushi,
    infos: ['Destaque da Semana', 'Japonesa']
  },
  '2': {
    title: 'La Dolce Vita Trattoria',
    description:
      'A La Dolce Vita Trattoria leva a autêntica cozinha italiana até você...',
    image: ladocevita,
    infos: ['Italiana']
  },
  '3': {
    title: 'Diablo',
    description: 'Experimente o sabor explosivo da culinária mexicana!',
    image: diablo,
    infos: ['Mexicana', 'Picante']
  },
  '4': {
    title: 'Star Wars',
    description:
      'Embarque em uma jornada intergaláctica com sabores exóticos...',
    image: starWars,
    infos: ['Temática', 'Exótica']
  }
}

const SaibaMais = () => {
  const { pratoId } = useParams() // Recebe o id do prato da URL

  // Agora pratoId é garantidamente uma das chaves ('1', '2', '3', '4')
  const prato = pratoId ? pratoData[pratoId] : null // Verifica se pratoId é válido

  if (!prato) {
    return <div>Prato não encontrado!</div>
  }

  return (
    <>
      <Header />
      <Banner image={prato.image} /> {/* Passando a imagem para o Banner */}
      <h2>{prato.title}</h2>
      <ProductsList
        pratos={[prato]}
        title="Detalhes do Prato"
        background="gray"
      />
      <Footer />
    </>
  )
}

export default SaibaMais
